/* @lc app=leetcode id=3655 lang=kotlin */ class Solution { fun xorAfterQueries(nums: IntArray, queries: Array<IntArray>): Int = 1_000_000_007L.let { M -> nums.size.let { n -> LongArray(n) { nums[it].toLong() }.let { a -> LongArray(100001).also { iv -> iv[1] = 1L }.also { iv -> (2..100000).forEach { i -> iv[i] = (M - (M / i) * iv[(M % i).toInt()] % M) % M } }.let { iv -> (Math.sqrt(n.toDouble()).toInt() + 1).let { B -> queries.filter { it[2] >= B }.forEach { (l, r, k, v) -> generateSequence(l) { it + k }.takeWhile { it <= r }.forEach { a[it] = a[it] * v % M } }.let { queries.filter { it[2] < B }.groupBy { it[2] }.forEach { (k, qs) -> LongArray(n) { 1L }.also { d -> qs.forEach { (l, r, _, v) -> d.set(l, d[l] * v % M).also { (l + (r - l) / k * k + k).let { last -> if (last < n) d[last] = d[last] * iv[v] % M } } } }.also { d -> (k until n).forEach { i -> d[i] = d[i] * d[i - k] % M } }.also { d -> (0 until n).forEach { i -> a[i] = a[i] * d[i] % M } } } }.let { a.fold(0L) { x, y -> x xor y }.toInt() } } } } } } }